import re, base64, pathlib
srv=pathlib.Path('/work/sts.bin').read_bytes()
# find base64-like sequences longer than 100 chars
def is_b64(s):
    try:
        base64.b64decode(s, validate=True)
        return True
    except Exception:
        return False

candidates=set()
for m in re.finditer(b'([A-Za-z0-9+/]{100,}={0,2})', srv):
    cand=m.group(1)
    if is_b64(cand):
        candidates.add(cand.decode())
print('found', len(candidates))
for c in list(candidates)[:5]:
    print(c[:80])

